# 8x16 cell, drawing area cols 0-6, rows 2-11 (caps) / 4-11 (lowercase)
# '#' = on. Each entry is 16 rows of 8 chars.
def C(*rows):
    g=['........']*2 + list(rows)
    g += ['........']*(16-len(g))
    return g[:16]

